$client=GuzzleFactory::getClient($Config);$scraper=new OpenBekenOtaScraper($Config->read('auto_update_channel'),$client);$OpenBekenHelper=new OpenBekenHelper(new GithubFlavoredMarkdownConverter(),$client,$scraper,$Config->read('auto_update_channel'));$releaseNotes=$OpenBekenHelper->getReleaseNotes();$changelog=$OpenBekenHelper->getChangelog();$recentReleases=$scraper->getRecentReleases(10);$hostHeader=trim((string)($_SERVER['HTTP_HOST']??$_SERVER['SERVER_NAME']??''));$detectedHost=preg_replace('/:\d+$/','',$hostHeader);if(str_starts_with($detectedHost,'[')&&str_ends_with($detectedHost,']'))$detectedHost=trim($detectedHost,'[]');$configuredOtaIp=trim((string)$Config->read('ota_server_ip'));if($configuredOtaIp===''||str_starts_with($configuredOtaIp,'172.30.'))$configuredOtaIp=$detectedHost;$configuredOtaPort=trim((string)$Config->read('ota_server_port'))?:(string)($_SERVER['SERVER_PORT']??'9542');?>
