<form class='upload-form' method='post' enctype='multipart/form-data' action='<?php echo _BASEURL_;?>upload'><div class="card upload-form-card mb-4"><div class="card-body"><h4 class="mb-3">OTA Server</h4><div class='row g-4 mb-4'><div class="col col-12 col-sm-9"><label for="ota_server_ip" class="form-label"><?php echo __('CONFIG_SERVER_IP','USER_CONFIG');?></label><input type="text" class="form-control" id="ota_server_ip" name='ota_server_ip' required value='<?php echo htmlspecialchars($configuredOtaIp,ENT_QUOTES,'UTF-8');?>'></div><div class="col col-12 col-sm-3"><label for="ota_server_port" class="form-label"><?php echo __('CONFIG_SERVER_PORT','USER_CONFIG');?></label><input type="text" class="form-control" id="ota_server_port" name='ota_server_port' required value='<?php echo htmlspecialchars($configuredOtaPort,ENT_QUOTES,'UTF-8');?>'></div></div>
<hr><h4 class="mb-3"><?php echo __('EXECUTION_TITLE','DEVICE_UPDATE');?></h4><div class="row g-3 mb-4"><div class="col-12 col-md-6"><label class="form-label"><?php echo __('EXECUTION_MODE','DEVICE_UPDATE');?></label><select class="form-select" name="update_mode"><option value="mass" selected><?php echo __('EXECUTION_MASS','DEVICE_UPDATE');?></option><option value="individual"><?php echo __('EXECUTION_INDIVIDUAL','DEVICE_UPDATE');?></option></select><div class="form-text"><?php echo __('EXECUTION_HELP','DEVICE_UPDATE');?></div></div></div>
